<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVersion\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Document\TemplateVersion\Application\Usecase\Retrieve\TemplateVersionRetrieveUsecase;
use Civi\Lughauth\Features\Document\TemplateVersion\Application\Usecase\Retrieve\TemplateVersionRetrieveResult;

class TemplateVersionRetrieveController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TemplateVersionRetrieveUsecase $retrieveUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/document/template-versions{uid}",
        tags: ["Template version"],
        description:"Create",
        parameters: [
               new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
          ],
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TemplateVersionApiDTO")),
              new OA\Response(response: 404, description: "Not found"),
          ]
    )]
    public function retrieve(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Retrieve Template version");
        $span = $this->startSpan("Retrieve Template version");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->retrieveUsecase->retrieve($uid);
            $value = $this->mapTemplateVersion($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapTemplateVersion(ServerRequestInterface $request, TemplateVersionRetrieveResult $value): TemplateVersionApiDTO
    {
        $this->logDebug("Map entity to output dto for Template version");
        $span = $this->startSpan("Map entity to output dto for Template version");
        try {
            $template = $value->getTemplate();
            $dto = new TemplateVersionApiDTO();
            $dto->uid = $value->getUid();
            $dto->template = $template ? ['$ref' => $template->uid()] : null;
            $dto->subject = $value->getSubject();
            $dto->contentHtml = $value->getContentHtml();
            $dto->contentText = $value->getContentText();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
